-- Server-owned invitation rooms precede, and atomically freeze into, the existing
-- canonical quote/shared-payment ledger. No timer releases or forgives payment.
-- Generated by `supabase migration new mealdeck_ordering_rooms`.
-- Independent MealDeck only; install after the exact Checkout-domain extension.
begin;
set local lock_timeout='5s';

do $guard$ begin
  if to_regclass('mealdeck_private.installation') is null or to_regnamespace('dishbee_private') is not null then
    raise exception 'mealdeck_ordering_independent_profile_required'; end if;
  if not exists(select 1 from mealdeck_private.installation where singleton and profile='mealdeck-independent-v1') then
    raise exception 'mealdeck_ordering_independent_profile_required'; end if;
  if to_regclass('mealdeck_private.payment_orders') is null
    or to_regclass('mealdeck_private.payment_collections') is null
    or to_regprocedure('mealdeck_private.valid_checkout_url(text)') is null
    or to_regprocedure('mealdeck_private.create_checkout_quote_for_actor(uuid,uuid,uuid,uuid,uuid,text,jsonb,jsonb,text,jsonb)') is null
    or to_regprocedure('public.mealdeck_bind_order_payment(uuid,text,text,text,text,boolean)') is null then
    raise exception 'mealdeck_ordering_previous_extensions_required'; end if;
  if (select md5(prosrc) from pg_proc where oid=
    'public.mealdeck_bind_order_payment(uuid,text,text,text,text,boolean)'::regprocedure)<>'0af7c9ec1caaed5c232c31bcfff54995' then
    raise exception 'mealdeck_ordering_unexpected_definition'; end if;
  -- Only the reviewed prior definitions or this exact additive revision may be
  -- replaced. A deliberate rerun is safe; unrelated local changes fail closed.
  if to_regprocedure('mealdeck_private.validate_checkout_packing(jsonb,jsonb)') is null
    or (select md5(prosrc) from pg_proc where oid=to_regprocedure('mealdeck_private.validate_checkout_packing(jsonb,jsonb)'))
      not in ('e54f35e707837cf63bf094f42a5f213b','1bb0941fae641c4dae62b6e7e37c2d3b') then
    raise exception 'mealdeck_ordering_unexpected_definition'; end if;
  if to_regprocedure('mealdeck_private.payment_collection_json(uuid)') is null
    or (select md5(prosrc) from pg_proc where oid=to_regprocedure('mealdeck_private.payment_collection_json(uuid)'))
      not in ('2a4a1a788a39fdc0fe0c1476bcea1281','d5468e6464453edf600d0bee38a08047') then
    raise exception 'mealdeck_ordering_unexpected_definition'; end if;
  if to_regprocedure('public.mealdeck_create_group_payment_room(uuid,uuid,uuid,text,uuid,text,jsonb,text,boolean)') is null
    or (select md5(prosrc) from pg_proc where oid=to_regprocedure('public.mealdeck_create_group_payment_room(uuid,uuid,uuid,text,uuid,text,jsonb,text,boolean)'))
      not in ('638ffa171b7afa4651a0c6a6f7f3b49e','5432af9540319483af3c0546356af271') then
    raise exception 'mealdeck_ordering_unexpected_definition'; end if;
  if to_regprocedure('public.mealdeck_prepare_group_payment(uuid,uuid,text,text,boolean,uuid,text,boolean)') is null
    or (select md5(prosrc) from pg_proc where oid=to_regprocedure('public.mealdeck_prepare_group_payment(uuid,uuid,text,text,boolean,uuid,text,boolean)'))
      not in ('f56a6a56445e4cd40cdabab86b3220b2','7c0bba5938d5f25241ef9c897cc59eeb') then
    raise exception 'mealdeck_ordering_unexpected_definition'; end if;
  if to_regprocedure('mealdeck_ops_private.kds_order_card(uuid,jsonb)') is null
    or (select md5(prosrc) from pg_proc where oid=to_regprocedure('mealdeck_ops_private.kds_order_card(uuid,jsonb)'))
      not in ('9090995cbfb061a89b8f2ba25e422d65','9c49af35d81442f4e3d4a98d14f0e14a') then
    raise exception 'mealdeck_ordering_unexpected_definition'; end if;
end $guard$;

-- Rerunning this exact migration must not overwrite separately changed room
-- routines. The table/function set is either wholly new or a reviewed rerun.
do $room_guard$ declare expected record; installed boolean:=to_regclass('mealdeck_private.ordering_rooms') is not null; begin
  if installed is distinct from (to_regclass('mealdeck_private.ordering_participants') is not null) then
    raise exception 'mealdeck_ordering_unexpected_definition'; end if;
  for expected in select * from (values
    ('mealdeck_private.ordering_person_name(text)','45b0d2fd9b5035fc980f79fa32678fe1'),
    ('mealdeck_private.validate_ordering_picks(jsonb)','2919fb9f00266818cc46aecdc817c15c'),
    ('mealdeck_private.expire_ordering_invitations(uuid)','5137c8d592878f5915473c77f69a6758'),
    ('mealdeck_private.lock_ordering_room(uuid,text)','aba33ccbedf49b54afe74d8ebf344097'),
    ('mealdeck_private.ordering_room_snapshot(uuid,text)','93810c827b77b36efc9be00c0f10819e'),
    ('public.mealdeck_create_ordering_room(uuid,uuid,uuid,uuid,text,uuid,text,text,text,text,jsonb,boolean,jsonb)','4c65ed16727b7d9a4d0b26a9b31c2afd'),
    ('public.mealdeck_ordering_invitation(uuid,text)','4c115989cb7dc38e7b95e0010cb2a056'),
    ('public.mealdeck_accept_ordering_invitation(uuid,text,text,text)','c62ddb4db4e7a929322c5f0cf0fc4b1b'),
    ('public.mealdeck_ordering_room_status(uuid,text)','95116fd51e6522df7f872f8679137e9d'),
    ('public.mealdeck_update_ordering_choices(uuid,text,bigint,jsonb)','ebd6ea90b6cdc6972bf9551b5b22a1f4'),
    ('public.mealdeck_set_ordering_ready(uuid,text,bigint,boolean)','5c60a704641b9414b9498651619bb311'),
    ('public.mealdeck_leave_ordering_room(uuid,text)','511f7b087b7ac297578b54077e052555'),
    ('public.mealdeck_remove_ordering_invitation(uuid,text,uuid)','bb682253c697a99f76a64e2cca20a4e2'),
    ('public.mealdeck_close_ordering_invitations(uuid,text)','2689d5263e8609652175f0663dff9e06'),
    ('public.mealdeck_finalize_ordering_room(uuid,text,uuid,text,bigint,jsonb,jsonb,text,uuid,jsonb,text,boolean)','542804bcf81957bd767b57c37ec3e75a'),
    ('public.mealdeck_ordering_payment_access(uuid,text,uuid,text,boolean)','fb59044cd841a5250aac3630017789a7'),
    ('public.mealdeck_ordering_payment_status(uuid,text)','c1fe7251472cd9c5af0a661bcde8f7fe'),
    ('public.mealdeck_ordering_payment_collections(uuid,text,uuid,text)','6191c966de75e04bb5c74082e661b622'),
    ('public.mealdeck_cancel_ordering_room(uuid,text,uuid,text)','4e1b2a6d68e25493e81f498dedc2d957')
  ) definitions(signature,source_hash) loop
    if (installed and to_regprocedure(expected.signature) is null)
      or (to_regprocedure(expected.signature) is not null and
        (select md5(prosrc) from pg_proc where oid=to_regprocedure(expected.signature))<>expected.source_hash) then
      raise exception 'mealdeck_ordering_unexpected_definition'; end if;
  end loop;
end $room_guard$;

create or replace function mealdeck_private.ordering_person_name(p_name text)
returns text language plpgsql immutable security invoker set search_path='' as $$
declare result text;
begin
  -- PostgreSQL length counts Unicode code points, matching the server contract.
  -- Reject controls before normalising spaces; a newline must never become a name.
  if p_name is null or p_name ~ U&'[\0001-\001F\007F-\009F\061C\200E\200F\2028-\202E\2066-\2069]' then
    raise exception 'mealdeck_ordering_name_invalid'; end if;
  result:=btrim(regexp_replace(p_name,U&'[\0020\00A0\1680\2000-\200A\202F\205F\3000\FEFF]+',' ','g'));
  if length(result) not between 1 and 32 then raise exception 'mealdeck_ordering_name_invalid'; end if;
  return result;
end $$;

create table if not exists mealdeck_private.ordering_rooms(
  id uuid primary key,
  tenant_id uuid not null references public.tenants(id),
  location_id uuid not null,
  owner_actor_hash text not null check(owner_actor_hash ~ '^[a-f0-9]{64}$'),
  owner_customer_id uuid references auth.users(id),
  owner_guest_id uuid references mealdeck_private.guest_sessions(id),
  create_attempt_id uuid not null,
  create_payload jsonb not null check(jsonb_typeof(create_payload)='object'),
  payment_mode text not null check(payment_mode in ('separate','organiser')),
  phase text not null default 'collecting' check(phase in ('collecting','finalizing','payment','cancelled')),
  fulfilment text not null check(fulfilment in ('pickup','curbside')),
  vehicle jsonb,
  cutlery_requested boolean not null,
  join_deadline timestamptz not null default clock_timestamp()+interval '3 minutes',
  invitations_closed_at timestamptz,
  revision bigint not null default 0 check(revision between 0 and 9007199254740991),
  quote_id uuid unique references mealdeck_private.checkout_quotes(id),
  order_id uuid unique references mealdeck_private.payment_orders(order_id),
  finalize_attempt_id uuid,
  frozen_at timestamptz,
  created_at timestamptz not null default clock_timestamp(),
  foreign key(tenant_id,location_id) references public.tenant_locations(tenant_id,id),
  foreign key(tenant_id,location_id,order_id) references public.orders(tenant_id,location_id,id),
  check(num_nonnulls(owner_customer_id,owner_guest_id)=1),
  check((phase='collecting' and quote_id is null and order_id is null and frozen_at is null)
    or (phase='finalizing' and quote_id is not null and order_id is null and finalize_attempt_id is not null)
    or (phase='payment' and quote_id is not null and order_id is not null and frozen_at is not null and finalize_attempt_id is not null)
    or phase='cancelled'),
  unique(owner_actor_hash,create_attempt_id)
);
create index if not exists ordering_rooms_actor_created_idx on mealdeck_private.ordering_rooms(owner_actor_hash,created_at desc);

create table if not exists mealdeck_private.ordering_participants(
  id uuid primary key,
  room_id uuid not null references mealdeck_private.ordering_rooms(id),
  slot_number integer not null check(slot_number between 1 and 10),
  display_name text not null check(display_name=mealdeck_private.ordering_person_name(display_name)),
  is_organiser boolean not null,
  invite_hash text unique check(invite_hash ~ '^[a-f0-9]{64}$'),
  actor_hash text check(actor_hash ~ '^[a-f0-9]{64}$'),
  state text not null check(state in ('invited','joined','ready','left','expired','removed')),
  picks jsonb not null default '[]'::jsonb check(jsonb_typeof(picks)='array'),
  version bigint not null default 0 check(version between 0 and 9007199254740991),
  joined_at timestamptz,
  ready_at timestamptz,
  bag_number integer check(bag_number between 1 and 10),
  share_id uuid unique references mealdeck_private.payment_shares(id),
  check(is_organiser=(slot_number=1)),
  check((is_organiser and invite_hash is null and actor_hash is not null and state in ('joined','ready'))
    or (not is_organiser and invite_hash is not null)),
  check((state in ('invited','expired','removed') and actor_hash is null)
    or (state in ('joined','ready','left') and actor_hash is not null)),
  check((bag_number is null)=(share_id is null)),
  unique(room_id,slot_number),unique(room_id,actor_hash),unique(room_id,bag_number)
);
alter table mealdeck_private.ordering_rooms enable row level security;
alter table mealdeck_private.ordering_participants enable row level security;
revoke all on table mealdeck_private.ordering_rooms,mealdeck_private.ordering_participants from public,anon,authenticated,service_role;

-- Only bounded source choices are stored. The trusted HTTP server validates the
-- current menu and later maps these exact revision-bound choices to canonical
-- SKUs/modifiers; prices remain authoritative in create_checkout_quote_for_actor.
create or replace function mealdeck_private.validate_ordering_picks(p_picks jsonb)
returns boolean language plpgsql immutable security invoker set search_path='' as $$
declare pick jsonb;choice record;cross_choice jsonb;source_pattern text:='^[a-z0-9]+(-[a-z0-9]+)*$';
begin
  if jsonb_typeof(p_picks) is distinct from 'array' then raise exception 'mealdeck_ordering_choices_invalid'; end if;
  if jsonb_array_length(p_picks)>60 or octet_length(p_picks::text)>200000 then raise exception 'mealdeck_ordering_choices_invalid'; end if;
  for pick in select value from jsonb_array_elements(p_picks) loop
    if jsonb_typeof(pick) is distinct from 'object'
      or pick-array['brandId','itemId','quantity','selections','crossSelections']::text[]<>'{}'::jsonb
      or jsonb_typeof(pick->'brandId') is distinct from 'string' or length(pick->>'brandId')>180
      or coalesce(pick->>'brandId','') !~ source_pattern
      or jsonb_typeof(pick->'itemId') is distinct from 'string' or length(pick->>'itemId')>180
      or coalesce(pick->>'itemId','') !~ source_pattern
      or jsonb_typeof(pick->'quantity') is distinct from 'number'
      or coalesce(pick->>'quantity','') !~ '^([1-9]|1[0-9]|20)$'
      or jsonb_typeof(pick->'selections') is distinct from 'object' then
      raise exception 'mealdeck_ordering_choices_invalid'; end if;
    if (select count(*) from jsonb_object_keys(pick->'selections'))>30 then raise exception 'mealdeck_ordering_choices_invalid'; end if;
    for choice in select * from jsonb_each(pick->'selections') loop
      if length(choice.key)>180 or choice.key !~ source_pattern or jsonb_typeof(choice.value) is distinct from 'array' then
        raise exception 'mealdeck_ordering_choices_invalid'; end if;
      if jsonb_array_length(choice.value)>30 or exists(select 1 from jsonb_array_elements(choice.value) o
        where jsonb_typeof(o) is distinct from 'string' or length(o#>>'{}')>180 or (o#>>'{}') !~ source_pattern) then
        raise exception 'mealdeck_ordering_choices_invalid'; end if;
    end loop;
    if pick ? 'crossSelections' then
      if jsonb_typeof(pick->'crossSelections') is distinct from 'array' then raise exception 'mealdeck_ordering_choices_invalid'; end if;
      if jsonb_array_length(pick->'crossSelections')>2 or jsonb_array_length(pick->'crossSelections')<>
        (select count(distinct x->>'slot') from jsonb_array_elements(pick->'crossSelections') x) then
        raise exception 'mealdeck_ordering_choices_invalid'; end if;
      for cross_choice in select value from jsonb_array_elements(pick->'crossSelections') loop
        if jsonb_typeof(cross_choice) is distinct from 'object'
          or cross_choice-array['slot','mode','brandId','itemId']::text[]<>'{}'::jsonb
          or coalesce(cross_choice->>'slot','') not in ('side','drink')
          or coalesce(cross_choice->>'mode','') not in ('upgrade','extra')
          or coalesce(cross_choice->>'brandId','') not in ('loadd','moktl')
          or jsonb_typeof(cross_choice->'itemId') is distinct from 'string' or length(cross_choice->>'itemId')>180
          or coalesce(cross_choice->>'itemId','') !~ source_pattern then raise exception 'mealdeck_ordering_choices_invalid'; end if;
      end loop;
    end if;
  end loop;
  if (select coalesce(sum((x->>'quantity')::integer),0) from jsonb_array_elements(p_picks) x)>60 then
    raise exception 'mealdeck_ordering_basket_limit'; end if;
  return true;
end $$;

-- Caller holds the room row lock. Use wall time after acquiring it, so an accept
-- queued before the deadline cannot join after the deadline while using now().
create or replace function mealdeck_private.expire_ordering_invitations(p_room uuid)
returns void language plpgsql security definer set search_path='' as $$
declare changed integer;
begin
  if exists(select 1 from mealdeck_private.ordering_rooms where id=p_room and phase='collecting'
    and join_deadline<=clock_timestamp() and invitations_closed_at is null) then
    update mealdeck_private.ordering_participants set state='expired',version=version+1
      where room_id=p_room and state='invited';
    get diagnostics changed=row_count;
    update mealdeck_private.ordering_rooms set invitations_closed_at=join_deadline,revision=revision+1 where id=p_room;
  end if;
end $$;

create or replace function mealdeck_private.lock_ordering_room(p_room uuid,p_actor_hash text)
returns mealdeck_private.ordering_rooms language plpgsql security definer set search_path='' as $$
declare r mealdeck_private.ordering_rooms%rowtype;
begin
  if p_actor_hash is null or p_actor_hash !~ '^[a-f0-9]{64}$' then raise exception 'mealdeck_ordering_room_unavailable'; end if;
  select * into r from mealdeck_private.ordering_rooms where id=p_room for update;
  if not found or not exists(select 1 from mealdeck_private.ordering_participants
    where room_id=p_room and actor_hash=p_actor_hash and state in ('joined','ready')) then
    raise exception 'mealdeck_ordering_room_unavailable'; end if;
  perform mealdeck_private.expire_ordering_invitations(p_room);
  select * into r from mealdeck_private.ordering_rooms where id=p_room;
  return r;
end $$;

create or replace function mealdeck_private.ordering_room_snapshot(p_room uuid,p_actor_hash text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r mealdeck_private.ordering_rooms%rowtype;v mealdeck_private.ordering_participants%rowtype;
  people jsonb;pending_count integer;joined_count integer;ready_count integer;bag_count integer;can_finalize boolean;
begin
  select * into r from mealdeck_private.ordering_rooms where id=p_room;
  select * into v from mealdeck_private.ordering_participants where room_id=p_room and actor_hash=p_actor_hash;
  if r.id is null or v.id is null then raise exception 'mealdeck_ordering_room_unavailable'; end if;
  select count(*) filter(where state='invited'),count(*) filter(where state in ('joined','ready')),
    count(*) filter(where state='ready'),count(*) filter(where state in ('joined','ready') and jsonb_array_length(picks)>0)
    into pending_count,joined_count,ready_count,bag_count from mealdeck_private.ordering_participants where room_id=p_room;
  can_finalize:=r.phase='collecting' and pending_count=0 and joined_count=ready_count and bag_count>0;
  select jsonb_agg(jsonb_build_object('participantId',p.id,'name',p.display_name,'isOrganiser',p.is_organiser,
    'state',p.state,'version',p.version,'bagNumber',p.bag_number,
    'shareId',case when v.is_organiser or p.id=v.id then p.share_id else null end,
    'paymentState',case when p.share_id is null then null
      when c.hold_reason is not null or (po.hold_reason is not null and c.captured_pence>0) then 'refund_review'
      when c.captured_pence=c.amount_pence then 'paid' when c.id is not null then 'pending' else 'unclaimed' end)
      ||case when v.is_organiser or p.id=v.id then jsonb_build_object('picks',p.picks) else '{}'::jsonb end
      order by p.slot_number) into people
    from mealdeck_private.ordering_participants p
      left join mealdeck_private.payment_collection_shares cs on cs.share_id=p.share_id and cs.active
      left join mealdeck_private.payment_collections c on c.id=cs.collection_id
      left join mealdeck_private.payment_orders po on po.order_id=r.order_id
    where p.room_id=p_room;
  return jsonb_build_object('schemaVersion',1,'roomId',r.id,'revision',r.revision,
    'phase',case when r.phase='collecting' and can_finalize then 'ready'
      when r.phase='payment' and exists(select 1 from mealdeck_private.payment_orders where order_id=r.order_id and cancel_requested_at is not null)
        then 'cancelled' else r.phase end,
    'paymentMode',r.payment_mode,'joinDeadline',r.join_deadline,
    'invitationsClosed',r.invitations_closed_at is not null,'serverNow',clock_timestamp(),'createdAt',r.created_at,
    'fulfilment',r.fulfilment,'vehicle',r.vehicle,'cutleryRequested',r.cutlery_requested,
    'viewer',jsonb_build_object('participantId',v.id,'role',case when v.is_organiser then 'organiser' else 'participant' end),
    'people',people,'pendingCount',pending_count,'joinedCount',joined_count,'readyCount',ready_count,
    'canFinalize',can_finalize and v.is_organiser,'orderId',r.order_id,'paymentRoomId',case when r.order_id is not null then r.id else null end);
end $$;

create or replace function mealdeck_private.validate_checkout_packing(p_selection jsonb,p_packing jsonb)
returns boolean language plpgsql immutable security invoker set search_path='' as $$
declare bag jsonb;allocation jsonb;line jsonb;number integer:=0;n integer;parent_qty integer;
begin
  if jsonb_typeof(p_packing) is distinct from 'object' or p_packing->'version' is distinct from '1'::jsonb
    or jsonb_typeof(p_packing->'separateBags') is distinct from 'boolean'
    or jsonb_typeof(p_packing->'cutleryRequested') is distinct from 'boolean'
    or jsonb_typeof(p_packing->'bags') is distinct from 'array'
    or jsonb_array_length(p_packing->'bags') not between 1 and 10
    or (p_packing->'separateBags'='false'::jsonb and jsonb_array_length(p_packing->'bags')<>1)
    or p_packing-array['version','separateBags','cutleryRequested','bags']::text[]<>'{}'::jsonb then
    raise exception 'mealdeck_checkout_invalid_packing'; end if;
  for bag in select value from jsonb_array_elements(p_packing->'bags') loop
    number:=number+1;
    if bag->'number' is distinct from to_jsonb(number)
      or jsonb_typeof(bag->'allocations') is distinct from 'array' or jsonb_array_length(bag->'allocations')=0
      or bag-array['number','allocations','name']::text[]<>'{}'::jsonb then raise exception 'mealdeck_checkout_invalid_packing'; end if;
    if bag ? 'name' and (jsonb_typeof(bag->'name') is distinct from 'string'
      or bag->>'name' is distinct from mealdeck_private.ordering_person_name(bag->>'name')) then
      raise exception 'mealdeck_checkout_invalid_packing'; end if;
    if (select count(*) from jsonb_array_elements(bag->'allocations')) <>
      (select count(distinct a->>'lineId') from jsonb_array_elements(bag->'allocations') a) then
      raise exception 'mealdeck_checkout_invalid_packing'; end if;
    for allocation in select value from jsonb_array_elements(bag->'allocations') loop
      if coalesce(allocation->>'quantity','') !~ '^([1-9]|1[0-9]|20)$'
        or allocation-array['lineId','quantity']::text[]<>'{}'::jsonb then raise exception 'mealdeck_checkout_invalid_packing'; end if;
      select value into line from jsonb_array_elements(p_selection) where value->>'lineId'=allocation->>'lineId';
      if not found then raise exception 'mealdeck_checkout_invalid_packing'; end if;
      if line->>'parentLineId' is not null then
        select (value->>'quantity')::integer into parent_qty from jsonb_array_elements(bag->'allocations')
          where value->>'lineId'=line->>'parentLineId';
        if not found or parent_qty<>(allocation->>'quantity')::integer then
          raise exception 'mealdeck_checkout_linked_extra_bag_mismatch'; end if;
      end if;
    end loop;
  end loop;
  for line in select value from jsonb_array_elements(p_selection) loop
    select coalesce(sum((a.value->>'quantity')::integer),0) into n
      from jsonb_array_elements(p_packing->'bags') b
      cross join lateral jsonb_array_elements(b.value->'allocations') a
      where a.value->>'lineId'=line->>'lineId';
    if n<>(line->>'quantity')::integer then raise exception 'mealdeck_checkout_incomplete_packing'; end if;
  end loop;
  return true;
end $$;

create or replace function mealdeck_private.payment_collection_json(p_collection uuid)
returns jsonb language sql stable security definer set search_path='' as $$
  select jsonb_build_object('collectionId',c.id,'attemptId',c.attempt_id,'orderId',c.order_id,
    'quoteId',o.quote_id,'roomId',o.room_id,'orderingRoomId',r.id,'tenantId',o.tenant_id,'locationId',o.location_id,
    'stripeAccount',o.stripe_account,'livemode',o.livemode,'method',c.method,'amountPence',c.amount_pence,
    'currency','gbp','requestHash',q.request_hash,'status',case
      when c.hold_reason is not null or (o.hold_reason is not null and c.captured_pence>0) then 'refund_review'
      when c.captured_pence=c.amount_pence then 'paid'
      when c.provider_cancelled_at is not null then 'cancelled'
      when c.session_id is not null or c.payment_intent_id is not null then 'pending' else 'reserved' end,
    'capturedPence',c.captured_pence,'refundedPence',c.refunded_pence,
    'cancelRequested',c.cancel_requested_at is not null or o.cancel_requested_at is not null,
    'coverRemaining',c.cover_remaining,'requestShareId',c.request_share_id,
    'shareIds',(select coalesce(jsonb_agg(s.share_id order by p.bag_number),'[]'::jsonb)
      from mealdeck_private.payment_collection_shares s join mealdeck_private.payment_shares p on p.id=s.share_id
      where s.collection_id=c.id),
    'sessionId',c.session_id,'sessionUrl',c.session_url,'paymentIntentId',c.payment_intent_id,
    'expiresAt',c.expires_at,'terminalLocationId',c.terminal_location_id,
    'email',case when c.customer_id is not null then (select email::text from auth.users where id=c.customer_id)
      when c.guest_id is not null then (select email from mealdeck_private.guest_sessions where id=c.guest_id) else null end)
  from mealdeck_private.payment_collections c join mealdeck_private.payment_orders o on o.order_id=c.order_id
    join mealdeck_private.checkout_quotes q on q.id=o.quote_id
    left join mealdeck_private.ordering_rooms r on r.order_id=o.order_id where c.id=p_collection
$$;

create or replace function public.mealdeck_create_group_payment_room(
 p_room uuid,p_quote uuid,p_customer uuid,p_guest_token_hash text,p_attempt uuid,p_split_mode text,
 p_share_tokens jsonb,p_stripe_account text,p_livemode boolean
) returns jsonb language plpgsql security definer set search_path='' as $$
declare q mealdeck_private.checkout_quotes%rowtype;p mealdeck_private.payment_orders%rowtype;
 o public.orders%rowtype;actor_data jsonb;g uuid;bag_count integer;tokens jsonb;
begin
  if p_room is null or p_attempt is null or p_split_mode is null or p_split_mode not in ('by_bag','equal')
    or p_stripe_account is null or p_stripe_account !~ '^acct_[A-Za-z0-9]+$' or p_livemode is null
    or jsonb_typeof(p_share_tokens) is distinct from 'array' then raise exception 'mealdeck_payment_room_invalid'; end if;
  select * into q from mealdeck_private.checkout_quotes where id=p_quote;
  if not found then raise exception 'mealdeck_checkout_quote_unavailable'; end if;
  actor_data:=mealdeck_private.payment_actor(q.tenant_id,q.location_id,p_customer,p_guest_token_hash);g:=(actor_data->>'guestId')::uuid;
  if q.customer_id is distinct from p_customer or q.guest_id is distinct from g or q.staff_id is not null then
    raise exception 'mealdeck_checkout_quote_unavailable'; end if;
  perform pg_advisory_xact_lock(hashtextextended('mealdeck-payment-create:'||coalesce(p_customer,g)::text||':'||p_attempt::text,0));
  select * into q from mealdeck_private.checkout_quotes where id=p_quote for update;
  bag_count:=jsonb_array_length(q.packing_plan->'bags');
  -- A one-person survivor is valid only through the locked ordering-room freeze.
  if exists(select 1 from mealdeck_private.ordering_rooms r where r.id=p_room and
    (r.phase not in ('finalizing','payment') or r.quote_id is distinct from p_quote
      or r.owner_customer_id is distinct from p_customer or r.owner_guest_id is distinct from g)) then
    raise exception 'mealdeck_ordering_freeze_required'; end if;
  if bag_count not between 1 and 10
    or (bag_count=1 and not exists(select 1 from mealdeck_private.ordering_rooms r
      where r.id=p_room and r.quote_id=p_quote and r.phase in ('finalizing','payment'))) or q.packing_plan->'separateBags' is distinct from 'true'::jsonb
    or jsonb_array_length(p_share_tokens)<>bag_count or exists(
      select 1 from jsonb_array_elements(p_share_tokens) t where jsonb_typeof(t) is distinct from 'object'
      or t-array['shareId','bagNumber','tokenHash']::text[]<>'{}'::jsonb
      or jsonb_typeof(t->'shareId') is distinct from 'string' or jsonb_typeof(t->'tokenHash') is distinct from 'string'
      or jsonb_typeof(t->'bagNumber') is distinct from 'number'
      or coalesce(t->>'shareId','') !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'
      or coalesce(t->>'bagNumber','') !~ '^(10|[1-9])$' or coalesce(t->>'tokenHash','') !~ '^[a-f0-9]{64}$') then
    raise exception 'mealdeck_payment_shares_invalid'; end if;
  if (select count(distinct t->>'shareId') from jsonb_array_elements(p_share_tokens) t)<>bag_count
    or (select count(distinct t->>'tokenHash') from jsonb_array_elements(p_share_tokens) t)<>bag_count
    or (select count(distinct t->>'bagNumber') from jsonb_array_elements(p_share_tokens) t)<>bag_count
    or exists(select 1 from jsonb_array_elements(p_share_tokens) t where not exists(
      select 1 from jsonb_array_elements(q.packing_plan->'bags') b where (b->>'number')::integer=(t->>'bagNumber')::integer)) then
    raise exception 'mealdeck_payment_shares_invalid'; end if;
  select * into p from mealdeck_private.payment_orders where quote_id=p_quote or room_id=p_room
    or (attempt_id=p_attempt and customer_id is not distinct from p_customer and guest_id is not distinct from g);
  if found then
    select jsonb_agg(jsonb_build_object('shareId',s.id,'bagNumber',s.bag_number,'tokenHash',s.token_hash) order by s.bag_number)
      into tokens from mealdeck_private.payment_shares s where s.order_id=p.order_id;
    if p.room_id is distinct from p_room or p.quote_id<>p_quote or p.attempt_id<>p_attempt
      or p.customer_id is distinct from p_customer or p.guest_id is distinct from g
      or p.split_mode<>p_split_mode or p.stripe_account<>p_stripe_account or p.livemode<>p_livemode
      or tokens is distinct from (select jsonb_agg(t order by (t->>'bagNumber')::integer) from jsonb_array_elements(p_share_tokens) t) then
      raise exception 'mealdeck_payment_attempt_conflict'; end if;
    return mealdeck_private.group_payment_snapshot(p.order_id,true,null);
  end if;
  if exists(select 1 from mealdeck_private.stripe_orders where quote_id=p_quote) then raise exception 'mealdeck_payment_online_overlap'; end if;
  perform mealdeck_private.assert_payment_open(q.tenant_id,q.location_id,g is not null);
  insert into public.group_order_rooms(id,tenant_id,location_id,status,payment_mode)
    values(p_room,q.tenant_id,q.location_id,'collecting','separate_host_balance');
  o:=mealdeck_private.materialize_payment_order(p_quote,p_customer,g,null,p_room);
  insert into mealdeck_private.payment_orders(order_id,quote_id,tenant_id,location_id,room_id,channel,
    customer_id,guest_id,attempt_id,split_mode,stripe_account,livemode,total_pence)
    values(o.id,q.id,q.tenant_id,q.location_id,p_room,'group',p_customer,g,p_attempt,p_split_mode,p_stripe_account,p_livemode,q.total_pence);
  update public.group_order_rooms set master_order_id=o.id where id=p_room;
  -- Allocate exact integer pennies. By-bag discounts use largest remainder;
  -- equal contributions allocate any remaining pennies to earlier bag numbers.
  with weights as (
    select (b->>'number')::integer bag_number,sum((a->>'quantity')::integer*(l->>'unit_pence')::integer)::bigint weight
      from jsonb_array_elements(q.packing_plan->'bags') b cross join jsonb_array_elements(b->'allocations') a
      join jsonb_array_elements(q.priced_lines) l on l->>'lineId'=a->>'lineId' group by b->>'number'
  ), parts as (
    select bag_number,case when p_split_mode='equal' then q.total_pence/bag_count else (q.total_pence::bigint*weight/q.gross_pence)::integer end base,
      case when p_split_mode='equal' then 0 else q.total_pence::bigint*weight%q.gross_pence end remainder from weights
  ), ranked as (
    select *,row_number() over(order by remainder desc,bag_number) rank,q.total_pence-sum(base) over() extra from parts
  ) insert into mealdeck_private.payment_shares(id,order_id,bag_number,token_hash,amount_pence)
    select (t->>'shareId')::uuid,o.id,r.bag_number,t->>'tokenHash',r.base+case when r.rank<=r.extra then 1 else 0 end
      from ranked r join jsonb_array_elements(p_share_tokens) t on (t->>'bagNumber')::integer=r.bag_number;
  if (select sum(amount_pence) from mealdeck_private.payment_shares where order_id=o.id)<>q.total_pence then
    raise exception 'mealdeck_payment_allocation_invalid'; end if;
  insert into public.mealdeck_ops_audit_log(tenant_id,location_id,actor_id,action,entity_type,entity_id,next_value)
    values(q.tenant_id,q.location_id,p_customer,'payment.group_created','order',o.id,
      jsonb_build_object('roomId',p_room,'splitMode',p_split_mode,'shareCount',bag_count,'totalPence',q.total_pence));
  return mealdeck_private.group_payment_snapshot(o.id,true,null);
end $$;

create or replace function public.mealdeck_prepare_group_payment(
 p_room uuid,p_customer uuid,p_guest_token_hash text,p_share_token_hash text,p_cover_remaining boolean,
 p_attempt uuid,p_stripe_account text,p_livemode boolean
) returns jsonb language plpgsql security definer set search_path='' as $$
declare a jsonb;actor jsonb;p mealdeck_private.payment_orders%rowtype;c mealdeck_private.payment_collections%rowtype;
  g uuid;share uuid;shares uuid[];
begin
  a:=mealdeck_private.group_payment_access(p_room,p_customer,p_guest_token_hash,p_share_token_hash);
  p:=mealdeck_private.lock_payment_order((a->>'orderId')::uuid);
  actor:=mealdeck_private.payment_actor(p.tenant_id,p.location_id,p_customer,p_guest_token_hash);g:=(actor->>'guestId')::uuid;
  share:=case when p_cover_remaining then null else (a->>'shareId')::uuid end;
  if p_cover_remaining is null or p_attempt is null or p.stripe_account is distinct from p_stripe_account or p.livemode is distinct from p_livemode
    or (p_cover_remaining and not (a->>'owner')::boolean) or (not p_cover_remaining and share is null) then
    raise exception 'mealdeck_payment_claim_forbidden'; end if;
  -- The organiser-pay mode is enforced here as well as in the room UI/API.
  if exists(select 1 from mealdeck_private.ordering_rooms r where r.id=p_room and r.payment_mode='organiser')
    and (not (a->>'owner')::boolean or not p_cover_remaining) then
    raise exception 'mealdeck_payment_claim_forbidden'; end if;
  -- Older payment pages assumed Bag 1 belonged to the organiser. New rooms may
  -- have an organiser who is not eating, so only the explicitly bound own share
  -- qualifies for pay-own; covering other people uses the existing cover action.
  if (a->>'owner')::boolean and not p_cover_remaining
    and exists(select 1 from mealdeck_private.ordering_rooms r where r.id=p_room)
    and not exists(select 1 from mealdeck_private.ordering_participants m
      where m.room_id=p_room and m.is_organiser and m.share_id=share) then
    raise exception 'mealdeck_payment_claim_forbidden'; end if;
  select * into c from mealdeck_private.payment_collections where order_id=p.order_id and attempt_id=p_attempt;
  if found then
    if c.customer_id is distinct from p_customer or c.guest_id is distinct from g or c.staff_id is not null
      or c.method<>'checkout' or c.request_share_id is distinct from share or c.cover_remaining<>p_cover_remaining then
      raise exception 'mealdeck_payment_attempt_conflict'; end if;
    return mealdeck_private.payment_collection_json(c.id);
  end if;
  perform mealdeck_private.assert_payment_open(p.tenant_id,p.location_id,g is not null);
  if p_cover_remaining then
    select array_agg(s.id order by s.bag_number) into shares from mealdeck_private.payment_shares s where s.order_id=p.order_id
      and not exists(select 1 from mealdeck_private.payment_collection_shares cs where cs.share_id=s.id and cs.active);
  else shares:=array[share]; end if;
  return mealdeck_private.reserve_payment_collection(p.order_id,p_customer,g,null,'checkout',shares,p_attempt,share,p_cover_remaining,null);
end $$;

create or replace function mealdeck_ops_private.kds_order_card(p_order uuid,p_evidence jsonb)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare card jsonb;o public.orders%rowtype;lines jsonb;items jsonb;
begin
  select * into o from public.orders where id=p_order;
  card:=mealdeck_ops_private.kds_order_card_before_item_readiness(p_order,p_evidence);
  select q.priced_lines into lines from mealdeck_private.stripe_orders s
    join mealdeck_private.checkout_quotes q on q.id=s.quote_id where s.order_id=p_order;
  select coalesce(jsonb_agg(x.value||jsonb_build_object(
    'checkout_line_id',i.checkout_line_id,'parent_checkout_line_id',i.parent_checkout_line_id,
    'base_unit_pence',i.base_unit_price_pence,'unit_pence',i.unit_price_pence,
    'brand_name',coalesce((select l->>'brand_name' from jsonb_array_elements(lines) l where l->>'lineId'=i.checkout_line_id),x.value->>'brand_name'),
    'modifier_details',i.modifiers,
    'bags',coalesce((select jsonb_agg(jsonb_build_object('number',b->'number','quantity',a->'quantity')
        ||case when b ? 'name' then jsonb_build_object('name',b->>'name') else '{}'::jsonb end order by (b->>'number')::integer)
      from jsonb_array_elements(o.packing_plan->'bags') b,jsonb_array_elements(b->'allocations') a
      where a->>'lineId'=i.checkout_line_id),'[]'::jsonb)) order by i.checkout_line_id,i.id),'[]'::jsonb)
    into items from jsonb_array_elements(card->'items') x(value)
      join public.order_items i on i.id=(x.value->>'order_item_id')::uuid and i.order_id=p_order;
  -- Each routed copy carries the same immutable bag/name allocation as its
  -- canonical master item, so packing and participant labels cannot diverge.
  return card||jsonb_build_object('items',items,'tickets',coalesce((select jsonb_agg(t||jsonb_build_object('items',
      coalesce((select jsonb_agg(ti||jsonb_build_object('brand_name',ci->>'brand_name','bags',ci->'bags') order by ti->>'order_item_id')
      from jsonb_array_elements(t->'items') ti join jsonb_array_elements(items) ci
        on ci->>'order_item_id'=ti->>'order_item_id'),'[]'::jsonb)) order by t->>'ticket_id')
      from jsonb_array_elements(card->'tickets') t),'[]'::jsonb),'accepted_at',o.accepted_at,
    'cutlery_requested',o.cutlery_requested,'packing_plan',o.packing_plan,
    'vehicle',case when o.fulfilment='curbside' then o.vehicle else null end);
end $$;

-- ORDERING_ROOM_RPCS
create or replace function public.mealdeck_create_ordering_room(
  p_room uuid,p_attempt uuid,p_tenant uuid,p_location uuid,p_actor_hash text,
  p_customer uuid,p_guest_token_hash text,p_name text,p_payment_mode text,
  p_fulfilment text,p_vehicle jsonb,p_cutlery boolean,p_invites jsonb
) returns jsonb language plpgsql security definer set search_path='' as $$
declare r mealdeck_private.ordering_rooms%rowtype;actor jsonb;guest uuid;name text;invites jsonb;
  invitation jsonb;payload jsonb;slot integer:=1;
begin
  if p_room is null or p_attempt is null or p_tenant is null or p_location is null
    or p_actor_hash is null or p_actor_hash !~ '^[a-f0-9]{64}$'
    or p_payment_mode is null or p_payment_mode not in ('separate','organiser')
    or p_fulfilment is null or p_fulfilment not in ('pickup','curbside') or p_cutlery is null
    or jsonb_typeof(p_invites) is distinct from 'array' then raise exception 'mealdeck_ordering_room_invalid'; end if;
  name:=mealdeck_private.ordering_person_name(p_name);
  if jsonb_array_length(p_invites)>9 then raise exception 'mealdeck_ordering_room_full'; end if;
  if p_fulfilment='curbside' then
    if jsonb_typeof(p_vehicle) is distinct from 'object'
      or length(btrim(coalesce(p_vehicle->>'make',''))) not between 2 and 60
      or length(btrim(coalesce(p_vehicle->>'colour',''))) not between 2 and 40
      or coalesce(p_vehicle->>'registrationLast4','') !~ '^[A-Z0-9]{4}$'
      or p_vehicle-array['make','colour','registrationLast4']::text[]<>'{}'::jsonb then
      raise exception 'mealdeck_checkout_vehicle_required'; end if;
  elsif p_vehicle is not null then raise exception 'mealdeck_checkout_vehicle_not_needed'; end if;
  for invitation in select value from jsonb_array_elements(p_invites) loop
    if jsonb_typeof(invitation) is distinct from 'object'
      or invitation-array['participantId','name','tokenHash']::text[]<>'{}'::jsonb
      or coalesce(invitation->>'participantId','') !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'
      or jsonb_typeof(invitation->'name') is distinct from 'string'
      or coalesce(invitation->>'tokenHash','') !~ '^[a-f0-9]{64}$' then
      raise exception 'mealdeck_ordering_invitation_invalid'; end if;
    perform mealdeck_private.ordering_person_name(invitation->>'name');
  end loop;
  if (select count(distinct x->>'participantId') from jsonb_array_elements(p_invites) x)<>jsonb_array_length(p_invites)
    or (select count(distinct x->>'tokenHash') from jsonb_array_elements(p_invites) x)<>jsonb_array_length(p_invites) then
    raise exception 'mealdeck_ordering_invitation_invalid'; end if;
  select coalesce(jsonb_agg(x||jsonb_build_object('name',mealdeck_private.ordering_person_name(x->>'name')) order by n),'[]'::jsonb)
    into invites from jsonb_array_elements(p_invites) with ordinality t(x,n);
  actor:=mealdeck_private.payment_actor(p_tenant,p_location,p_customer,p_guest_token_hash);
  guest:=(actor->>'guestId')::uuid;
  payload:=jsonb_build_object('name',name,'paymentMode',p_payment_mode,'fulfilment',p_fulfilment,
    'vehicle',p_vehicle,'cutleryRequested',p_cutlery,'invites',invites);
  perform pg_advisory_xact_lock(hashtextextended('mealdeck-ordering-create:'||p_actor_hash||':'||p_attempt::text,0));
  select * into r from mealdeck_private.ordering_rooms where id=p_room
    or (owner_actor_hash=p_actor_hash and create_attempt_id=p_attempt) for update;
  if found then
    if r.id<>p_room or r.owner_actor_hash<>p_actor_hash or r.create_attempt_id<>p_attempt
      or r.tenant_id<>p_tenant or r.location_id<>p_location
      or r.owner_customer_id is distinct from p_customer or r.owner_guest_id is distinct from guest
      or r.create_payload is distinct from payload then raise exception 'mealdeck_ordering_attempt_conflict'; end if;
    perform mealdeck_private.expire_ordering_invitations(p_room);
    return mealdeck_private.ordering_room_snapshot(p_room,p_actor_hash);
  end if;
  if (select count(*) from mealdeck_private.ordering_rooms where owner_actor_hash=p_actor_hash
    and created_at>clock_timestamp()-interval '5 minutes')>=20 then raise exception 'mealdeck_ordering_retry_later'; end if;
  insert into mealdeck_private.ordering_rooms(id,tenant_id,location_id,owner_actor_hash,owner_customer_id,owner_guest_id,
    create_attempt_id,create_payload,payment_mode,fulfilment,vehicle,cutlery_requested)
    values(p_room,p_tenant,p_location,p_actor_hash,p_customer,guest,p_attempt,payload,p_payment_mode,p_fulfilment,p_vehicle,p_cutlery);
  insert into mealdeck_private.ordering_participants(id,room_id,slot_number,display_name,is_organiser,actor_hash,state,joined_at)
    values(gen_random_uuid(),p_room,1,name,true,p_actor_hash,'joined',clock_timestamp());
  for invitation in select value from jsonb_array_elements(invites) loop
    slot:=slot+1;
    insert into mealdeck_private.ordering_participants(id,room_id,slot_number,display_name,is_organiser,invite_hash,state)
      values((invitation->>'participantId')::uuid,p_room,slot,invitation->>'name',false,invitation->>'tokenHash','invited');
  end loop;
  return mealdeck_private.ordering_room_snapshot(p_room,p_actor_hash);
end $$;

create or replace function public.mealdeck_ordering_invitation(p_room uuid,p_invite_hash text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r mealdeck_private.ordering_rooms%rowtype;p mealdeck_private.ordering_participants%rowtype;
begin
  if p_invite_hash is null or p_invite_hash !~ '^[a-f0-9]{64}$' then raise exception 'mealdeck_ordering_invitation_unavailable'; end if;
  select * into r from mealdeck_private.ordering_rooms where id=p_room for update;
  if not found then raise exception 'mealdeck_ordering_invitation_unavailable'; end if;
  select * into p from mealdeck_private.ordering_participants where room_id=p_room and invite_hash=p_invite_hash;
  if not found then raise exception 'mealdeck_ordering_invitation_unavailable'; end if;
  perform mealdeck_private.expire_ordering_invitations(p_room);
  select * into r from mealdeck_private.ordering_rooms where id=p_room;
  select * into p from mealdeck_private.ordering_participants where id=p.id;
  return jsonb_build_object('schemaVersion',1,'roomId',r.id,'organiserName',
    (select display_name from mealdeck_private.ordering_participants where room_id=p_room and is_organiser),
    'invitedName',p.display_name,'paymentMode',r.payment_mode,'joinDeadline',r.join_deadline,'serverNow',clock_timestamp(),
    'joinable',r.phase='collecting' and p.state='invited' and r.invitations_closed_at is null and r.join_deadline>clock_timestamp(),
    'state',p.state);
end $$;

create or replace function public.mealdeck_accept_ordering_invitation(p_room uuid,p_invite_hash text,p_actor_hash text,p_name text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r mealdeck_private.ordering_rooms%rowtype;p mealdeck_private.ordering_participants%rowtype;name text;
begin
  if p_invite_hash is null or p_invite_hash !~ '^[a-f0-9]{64}$'
    or p_actor_hash is null or p_actor_hash !~ '^[a-f0-9]{64}$' then raise exception 'mealdeck_ordering_invitation_unavailable'; end if;
  name:=mealdeck_private.ordering_person_name(p_name);
  select * into r from mealdeck_private.ordering_rooms where id=p_room for update;
  if not found then raise exception 'mealdeck_ordering_invitation_unavailable'; end if;
  select * into p from mealdeck_private.ordering_participants where room_id=p_room and invite_hash=p_invite_hash;
  if not found then raise exception 'mealdeck_ordering_invitation_unavailable'; end if;
  perform mealdeck_private.expire_ordering_invitations(p_room);
  select * into r from mealdeck_private.ordering_rooms where id=p_room;
  select * into p from mealdeck_private.ordering_participants where id=p.id;
  -- A network replay can recover the original membership, never change its name
  -- or transfer an already accepted invitation to another browser actor.
  if p.actor_hash=p_actor_hash and p.state in ('joined','ready') then
    return mealdeck_private.ordering_room_snapshot(p_room,p_actor_hash); end if;
  if r.phase<>'collecting' or p.state<>'invited' or p.actor_hash is not null
    or r.invitations_closed_at is not null or r.join_deadline<=clock_timestamp() then
    raise exception 'mealdeck_ordering_invitation_unavailable'; end if;
  if exists(select 1 from mealdeck_private.ordering_participants where room_id=p_room and actor_hash=p_actor_hash) then
    raise exception 'mealdeck_ordering_already_joined'; end if;
  update mealdeck_private.ordering_participants set actor_hash=p_actor_hash,display_name=name,state='joined',
    joined_at=clock_timestamp(),version=version+1 where id=p.id;
  update mealdeck_private.ordering_rooms set revision=revision+1 where id=p_room;
  return mealdeck_private.ordering_room_snapshot(p_room,p_actor_hash);
end $$;

create or replace function public.mealdeck_ordering_room_status(p_room uuid,p_actor_hash text)
returns jsonb language plpgsql security definer set search_path='' as $$
begin
  perform mealdeck_private.lock_ordering_room(p_room,p_actor_hash);
  return mealdeck_private.ordering_room_snapshot(p_room,p_actor_hash);
end $$;

create or replace function public.mealdeck_update_ordering_choices(p_room uuid,p_actor_hash text,p_expected_version bigint,p_picks jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r mealdeck_private.ordering_rooms%rowtype;p mealdeck_private.ordering_participants%rowtype;quantity integer;
begin
  r:=mealdeck_private.lock_ordering_room(p_room,p_actor_hash);
  if r.phase<>'collecting' then raise exception 'mealdeck_ordering_frozen'; end if;
  select * into p from mealdeck_private.ordering_participants where room_id=p_room and actor_hash=p_actor_hash;
  if p_expected_version is null or p.version<>p_expected_version then raise exception 'mealdeck_ordering_version_conflict'; end if;
  perform mealdeck_private.validate_ordering_picks(p_picks);
  select coalesce(sum((x->>'quantity')::integer),0) into quantity from mealdeck_private.ordering_participants m
    cross join jsonb_array_elements(m.picks) x where m.room_id=p_room and m.id<>p.id and m.state in ('joined','ready');
  if quantity+(select coalesce(sum((x->>'quantity')::integer),0) from jsonb_array_elements(p_picks) x)>60 then
    raise exception 'mealdeck_ordering_basket_limit'; end if;
  update mealdeck_private.ordering_participants set picks=p_picks,state='joined',ready_at=null,version=version+1 where id=p.id;
  update mealdeck_private.ordering_rooms set revision=revision+1 where id=p_room;
  return mealdeck_private.ordering_room_snapshot(p_room,p_actor_hash);
end $$;

create or replace function public.mealdeck_set_ordering_ready(p_room uuid,p_actor_hash text,p_expected_version bigint,p_ready boolean)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r mealdeck_private.ordering_rooms%rowtype;p mealdeck_private.ordering_participants%rowtype;
begin
  r:=mealdeck_private.lock_ordering_room(p_room,p_actor_hash);
  if r.phase<>'collecting' then raise exception 'mealdeck_ordering_frozen'; end if;
  select * into p from mealdeck_private.ordering_participants where room_id=p_room and actor_hash=p_actor_hash;
  if p_expected_version is null or p.version<>p_expected_version then raise exception 'mealdeck_ordering_version_conflict'; end if;
  if p_ready is null or (p_ready and not p.is_organiser and jsonb_array_length(p.picks)=0) then
    raise exception 'mealdeck_ordering_choices_required'; end if;
  if (p.state='ready') is distinct from p_ready then
    update mealdeck_private.ordering_participants set state=case when p_ready then 'ready' else 'joined' end,
      ready_at=case when p_ready then clock_timestamp() else null end,version=version+1 where id=p.id;
    update mealdeck_private.ordering_rooms set revision=revision+1 where id=p_room;
  end if;
  return mealdeck_private.ordering_room_snapshot(p_room,p_actor_hash);
end $$;

create or replace function public.mealdeck_leave_ordering_room(p_room uuid,p_actor_hash text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r mealdeck_private.ordering_rooms%rowtype;p mealdeck_private.ordering_participants%rowtype;
begin
  r:=mealdeck_private.lock_ordering_room(p_room,p_actor_hash);
  if r.phase<>'collecting' then raise exception 'mealdeck_ordering_frozen'; end if;
  select * into p from mealdeck_private.ordering_participants where room_id=p_room and actor_hash=p_actor_hash;
  if p.is_organiser then raise exception 'mealdeck_ordering_organiser_required'; end if;
  update mealdeck_private.ordering_participants set state='left',picks='[]'::jsonb,ready_at=null,version=version+1 where id=p.id;
  update mealdeck_private.ordering_rooms set revision=revision+1 where id=p_room;
  return mealdeck_private.ordering_room_snapshot(p_room,p_actor_hash);
end $$;

create or replace function public.mealdeck_remove_ordering_invitation(p_room uuid,p_actor_hash text,p_participant uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r mealdeck_private.ordering_rooms%rowtype;p mealdeck_private.ordering_participants%rowtype;
begin
  r:=mealdeck_private.lock_ordering_room(p_room,p_actor_hash);
  if r.owner_actor_hash<>p_actor_hash then raise exception 'mealdeck_ordering_organiser_required'; end if;
  if r.phase<>'collecting' then raise exception 'mealdeck_ordering_frozen'; end if;
  select * into p from mealdeck_private.ordering_participants where id=p_participant and room_id=p_room and not is_organiser;
  if not found or p.state not in ('invited','expired','removed') then raise exception 'mealdeck_ordering_invitation_unavailable'; end if;
  if p.state='invited' then
    update mealdeck_private.ordering_participants set state='removed',version=version+1 where id=p.id;
    update mealdeck_private.ordering_rooms set revision=revision+1 where id=p_room;
  end if;
  return mealdeck_private.ordering_room_snapshot(p_room,p_actor_hash);
end $$;

create or replace function public.mealdeck_close_ordering_invitations(p_room uuid,p_actor_hash text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r mealdeck_private.ordering_rooms%rowtype;
begin
  r:=mealdeck_private.lock_ordering_room(p_room,p_actor_hash);
  if r.owner_actor_hash<>p_actor_hash then raise exception 'mealdeck_ordering_organiser_required'; end if;
  if r.phase<>'collecting' then raise exception 'mealdeck_ordering_frozen'; end if;
  if r.invitations_closed_at is null then
    update mealdeck_private.ordering_participants set state='removed',version=version+1 where room_id=p_room and state='invited';
    update mealdeck_private.ordering_rooms set invitations_closed_at=clock_timestamp(),revision=revision+1 where id=p_room;
  end if;
  return mealdeck_private.ordering_room_snapshot(p_room,p_actor_hash);
end $$;

-- FINALIZE_AND_PAYMENT_BRIDGE
create or replace function public.mealdeck_finalize_ordering_room(
  p_room uuid,p_actor_hash text,p_customer uuid,p_guest_token_hash text,
  p_expected_revision bigint,p_selection jsonb,p_packing jsonb,p_request_hash text,
  p_attempt uuid,p_share_tokens jsonb,p_stripe_account text,p_livemode boolean
) returns jsonb language plpgsql security definer set search_path='' as $$
declare r mealdeck_private.ordering_rooms%rowtype;actor jsonb;guest uuid;q mealdeck_private.checkout_quotes%rowtype;
  po mealdeck_private.payment_orders%rowtype;person record;bag jsonb;pick jsonb;line jsonb;
  line_number integer:=0;bag_count integer;tokens jsonb;quote jsonb;payment jsonb;
begin
  r:=mealdeck_private.lock_ordering_room(p_room,p_actor_hash);
  if r.owner_actor_hash<>p_actor_hash then raise exception 'mealdeck_ordering_organiser_required'; end if;
  actor:=mealdeck_private.payment_actor(r.tenant_id,r.location_id,p_customer,p_guest_token_hash);
  guest:=(actor->>'guestId')::uuid;
  if r.owner_customer_id is distinct from p_customer or r.owner_guest_id is distinct from guest then
    raise exception 'mealdeck_ordering_owner_identity_required'; end if;
  if p_attempt is null or p_expected_revision is null or p_request_hash is null or p_request_hash !~ '^[a-f0-9]{64}$'
    or p_stripe_account is null or p_stripe_account !~ '^acct_[A-Za-z0-9]+$' or p_livemode is null
    or jsonb_typeof(p_share_tokens) is distinct from 'array' then raise exception 'mealdeck_ordering_freeze_invalid'; end if;
  -- A successful freeze always recovers its one immutable quote/order. No retry
  -- reprices a paid basket or creates another order if the HTTP response was lost.
  if r.phase='payment' then
    select * into q from mealdeck_private.checkout_quotes where id=r.quote_id;
    select * into po from mealdeck_private.payment_orders where order_id=r.order_id;
    select jsonb_agg(jsonb_build_object('shareId',s.id,'bagNumber',s.bag_number,'tokenHash',s.token_hash) order by s.bag_number)
      into tokens from mealdeck_private.payment_shares s where s.order_id=r.order_id;
    if r.finalize_attempt_id is distinct from p_attempt or q.selection is distinct from p_selection
      or q.packing_plan is distinct from p_packing or q.request_hash is distinct from p_request_hash
      or po.stripe_account is distinct from p_stripe_account or po.livemode is distinct from p_livemode
      or tokens is distinct from (select jsonb_agg(t order by (t->>'bagNumber')::integer) from jsonb_array_elements(p_share_tokens) t) then
      raise exception 'mealdeck_ordering_attempt_conflict'; end if;
    return mealdeck_private.ordering_room_snapshot(p_room,p_actor_hash);
  end if;
  if r.phase<>'collecting' then raise exception 'mealdeck_ordering_frozen'; end if;
  if r.revision<>p_expected_revision then raise exception 'mealdeck_ordering_revision_conflict'; end if;
  if exists(select 1 from mealdeck_private.ordering_participants where room_id=p_room and state in ('invited','joined')) then
    raise exception 'mealdeck_ordering_not_ready'; end if;
  select count(*) into bag_count from mealdeck_private.ordering_participants
    where room_id=p_room and state='ready' and jsonb_array_length(picks)>0;
  if bag_count not between 1 and 10 then raise exception 'mealdeck_ordering_choices_required'; end if;
  if jsonb_typeof(p_selection) is distinct from 'array' or jsonb_typeof(p_packing) is distinct from 'object'
    or jsonb_typeof(p_packing->'bags') is distinct from 'array' then raise exception 'mealdeck_ordering_freeze_invalid'; end if;
  if jsonb_array_length(p_selection) not between 1 and 180 or jsonb_array_length(p_packing->'bags')<>bag_count
    or p_packing->'separateBags' is distinct from 'true'::jsonb
    or p_packing->'cutleryRequested' is distinct from to_jsonb(r.cutlery_requested) then
    raise exception 'mealdeck_ordering_packing_mismatch'; end if;
  perform mealdeck_private.validate_checkout_packing(p_selection,p_packing);
  -- Each canonical line belongs to exactly one person. A person may choose the
  -- same dish as another person, but their lines must not be merged across bags.
  if exists(select 1 from jsonb_array_elements(p_packing->'bags') b
    cross join jsonb_array_elements(b->'allocations') a group by a->>'lineId' having count(*)<>1) then
    raise exception 'mealdeck_ordering_packing_mismatch'; end if;
  for person in select p.*,row_number() over(order by p.slot_number)::integer computed_bag
    from mealdeck_private.ordering_participants p where room_id=p_room and state='ready' and jsonb_array_length(picks)>0 loop
    bag:=p_packing->'bags'->(person.computed_bag-1);
    if bag->>'name' is distinct from person.display_name or bag->'number' is distinct from to_jsonb(person.computed_bag) then
      raise exception 'mealdeck_ordering_packing_mismatch'; end if;
    for pick in select value from jsonb_array_elements(person.picks) loop
      line_number:=line_number+1;
      select value into line from jsonb_array_elements(p_selection)
        where value->>'lineId'='line-'||line_number::text and value->>'parentLineId' is null;
      if not found or line->'quantity' is distinct from pick->'quantity'
        or not exists(select 1 from jsonb_array_elements(bag->'allocations') a
          where a->>'lineId'=line->>'lineId' and a->'quantity'=pick->'quantity') then
        raise exception 'mealdeck_ordering_choices_mismatch'; end if;
    end loop;
  end loop;
  if (select count(*) from jsonb_array_elements(p_selection) l where l->>'parentLineId' is null)<>line_number then
    raise exception 'mealdeck_ordering_choices_mismatch'; end if;
  quote:=mealdeck_private.create_checkout_quote_for_identity(r.tenant_id,r.location_id,p_customer,guest,
    r.fulfilment,r.vehicle,p_selection,p_request_hash,p_packing);
  -- This uncommitted phase permits the existing ledger's single-bag extension;
  -- no other transaction can observe or claim this room until freeze commits.
  update mealdeck_private.ordering_rooms set phase='finalizing',quote_id=(quote->>'quoteId')::uuid,
    finalize_attempt_id=p_attempt where id=p_room;
  payment:=public.mealdeck_create_group_payment_room(p_room,(quote->>'quoteId')::uuid,p_customer,p_guest_token_hash,
    p_attempt,'by_bag',p_share_tokens,p_stripe_account,p_livemode);
  with ranked as (
    select id,row_number() over(order by slot_number)::integer bag_number from mealdeck_private.ordering_participants
      where room_id=p_room and state='ready' and jsonb_array_length(picks)>0
  ) update mealdeck_private.ordering_participants p set bag_number=x.bag_number,share_id=s.id
      from ranked x join mealdeck_private.payment_shares s on s.order_id=(payment->>'orderId')::uuid and s.bag_number=x.bag_number
      where p.id=x.id;
  update public.order_items i set group_participant_id=p.id,group_participant_name=p.display_name
    from mealdeck_private.ordering_participants p,jsonb_array_elements(p_packing->'bags') b,jsonb_array_elements(b->'allocations') a
    where p.room_id=p_room and p.bag_number=(b->>'number')::integer and i.order_id=(payment->>'orderId')::uuid
      and i.checkout_line_id=a->>'lineId';
  if exists(select 1 from public.order_items where order_id=(payment->>'orderId')::uuid and
    (group_participant_id is null or group_participant_name is null)) then raise exception 'mealdeck_ordering_packing_mismatch'; end if;
  update mealdeck_private.ordering_rooms set phase='payment',order_id=(payment->>'orderId')::uuid,
    frozen_at=clock_timestamp(),invitations_closed_at=coalesce(invitations_closed_at,clock_timestamp()),revision=revision+1 where id=p_room;
  return mealdeck_private.ordering_room_snapshot(p_room,p_actor_hash);
end $$;

-- Internal bridge: an accepted browser can access its own share, but still needs
-- a current verified member/guest identity before starting a payment. No browser
-- response may expose this service-only return value's shareTokenHash.
create or replace function public.mealdeck_ordering_payment_access(
  p_room uuid,p_actor_hash text,p_customer uuid,p_guest_token_hash text,p_cover_remaining boolean
) returns jsonb language plpgsql security definer set search_path='' as $$
declare r mealdeck_private.ordering_rooms%rowtype;p mealdeck_private.ordering_participants%rowtype;actor jsonb;token_hash text;
begin
  r:=mealdeck_private.lock_ordering_room(p_room,p_actor_hash);
  if r.phase<>'payment' or r.order_id is null then raise exception 'mealdeck_ordering_payment_unavailable'; end if;
  select * into p from mealdeck_private.ordering_participants where room_id=p_room and actor_hash=p_actor_hash;
  actor:=mealdeck_private.payment_actor(r.tenant_id,r.location_id,p_customer,p_guest_token_hash);
  if p.is_organiser and (r.owner_customer_id is distinct from p_customer or r.owner_guest_id is distinct from (actor->>'guestId')::uuid) then
    raise exception 'mealdeck_ordering_owner_identity_required'; end if;
  if p_cover_remaining is null or (p_cover_remaining and not p.is_organiser)
    or (not p_cover_remaining and p.share_id is null)
    or (r.payment_mode='organiser' and (not p.is_organiser or not p_cover_remaining)) then
    raise exception 'mealdeck_payment_claim_forbidden'; end if;
  if not p_cover_remaining then select s.token_hash into token_hash from mealdeck_private.payment_shares s where s.id=p.share_id; end if;
  return jsonb_build_object('roomId',r.id,'shareTokenHash',token_hash,'participantId',p.id,
    'owner',p.is_organiser,'paymentMode',r.payment_mode);
end $$;

-- Financial reads use the accepted room capability directly. They never invent
-- or impersonate the owner's stored Auth/guest identity to call another API.
create or replace function public.mealdeck_ordering_payment_status(p_room uuid,p_actor_hash text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r mealdeck_private.ordering_rooms%rowtype;p mealdeck_private.ordering_participants%rowtype;
begin
  r:=mealdeck_private.lock_ordering_room(p_room,p_actor_hash);
  if r.order_id is null then return null; end if;
  select * into p from mealdeck_private.ordering_participants where room_id=p_room and actor_hash=p_actor_hash;
  if not p.is_organiser and p.share_id is null then raise exception 'mealdeck_ordering_payment_unavailable'; end if;
  return mealdeck_private.group_payment_snapshot(r.order_id,p.is_organiser,p.share_id);
end $$;

-- Provider IDs/email here are server-internal reconciliation data, exactly as in
-- group_payment_collections; only payerAccess authorises a resumable session URL.
create or replace function public.mealdeck_ordering_payment_collections(
  p_room uuid,p_actor_hash text,p_customer uuid,p_guest_token_hash text
) returns jsonb language plpgsql security definer set search_path='' as $$
declare r mealdeck_private.ordering_rooms%rowtype;p mealdeck_private.ordering_participants%rowtype;actor jsonb;result jsonb;
begin
  r:=mealdeck_private.lock_ordering_room(p_room,p_actor_hash);
  if r.order_id is null then return '[]'::jsonb; end if;
  select * into p from mealdeck_private.ordering_participants where room_id=p_room and actor_hash=p_actor_hash;
  if p_customer is not null or p_guest_token_hash is not null then
    actor:=mealdeck_private.payment_actor(r.tenant_id,r.location_id,p_customer,p_guest_token_hash); end if;
  select coalesce(jsonb_agg(mealdeck_private.payment_collection_json(c.id)||jsonb_build_object('payerAccess',
    actor is not null and c.staff_id is null and c.customer_id is not distinct from (actor->>'customerId')::uuid
      and c.guest_id is not distinct from (actor->>'guestId')::uuid) order by c.created_at),'[]'::jsonb) into result
    from mealdeck_private.payment_collections c where c.order_id=r.order_id and
      (p.is_organiser or exists(select 1 from mealdeck_private.payment_collection_shares cs where cs.collection_id=c.id and cs.share_id=p.share_id));
  return result;
end $$;

create or replace function public.mealdeck_cancel_ordering_room(p_room uuid,p_actor_hash text,p_customer uuid,p_guest_token_hash text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r mealdeck_private.ordering_rooms%rowtype;actor jsonb;cancelled jsonb;
begin
  r:=mealdeck_private.lock_ordering_room(p_room,p_actor_hash);
  if r.owner_actor_hash<>p_actor_hash then raise exception 'mealdeck_ordering_organiser_required'; end if;
  actor:=mealdeck_private.payment_actor(r.tenant_id,r.location_id,p_customer,p_guest_token_hash);
  if r.owner_customer_id is distinct from p_customer or r.owner_guest_id is distinct from (actor->>'guestId')::uuid then
    raise exception 'mealdeck_ordering_owner_identity_required'; end if;
  if r.order_id is not null then
    cancelled:=public.mealdeck_cancel_group_payment_room(p_room,p_customer,p_guest_token_hash);
  else cancelled:=jsonb_build_object('collectionsToCancel','[]'::jsonb,'refundReviewRequired',false); end if;
  if r.phase<>'cancelled' then
    update mealdeck_private.ordering_participants set state='removed',version=version+1 where room_id=p_room and state='invited';
    update mealdeck_private.ordering_rooms set phase='cancelled',revision=revision+1,
      invitations_closed_at=coalesce(invitations_closed_at,clock_timestamp()) where id=p_room;
  end if;
  return jsonb_build_object('room',mealdeck_private.ordering_room_snapshot(p_room,p_actor_hash),
    'collectionsToCancel',cancelled->'collectionsToCancel','refundReviewRequired',cancelled->'refundReviewRequired');
end $$;

-- ACCESS_GRANTS
do $access$ declare f record; begin
  for f in select p.oid::regprocedure signature,n.nspname schema_name from pg_proc p
    join pg_namespace n on n.oid=p.pronamespace where
    (n.nspname='mealdeck_private' and p.proname in ('ordering_person_name','validate_ordering_picks','expire_ordering_invitations',
      'lock_ordering_room','ordering_room_snapshot'))
    or (n.nspname='public' and p.proname in ('mealdeck_create_ordering_room','mealdeck_ordering_invitation',
      'mealdeck_accept_ordering_invitation','mealdeck_ordering_room_status','mealdeck_update_ordering_choices','mealdeck_set_ordering_ready',
      'mealdeck_leave_ordering_room','mealdeck_remove_ordering_invitation','mealdeck_close_ordering_invitations',
      'mealdeck_finalize_ordering_room','mealdeck_ordering_payment_access','mealdeck_ordering_payment_status',
      'mealdeck_ordering_payment_collections','mealdeck_cancel_ordering_room')) loop
    execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
    if f.schema_name='public' then execute format('grant execute on function %s to service_role',f.signature); end if;
  end loop;
end $access$;

commit;
